%[text] # 处理XL-80导出的数据
close all;
clear; clc;
cd(fileparts(which ("start_up.m")));

set(groot, 'DefaultAxesFontName', 'Times New Roman', 'DefaultAxesFontSize', 12);
set(groot, 'DefaultTextFontName', 'Times New Roman', 'DefaultTextFontSize', 12);
set(groot, 'DefaultAxesXMinorTick', 'on');

GEOMETRIC_ERROR_MAP = 'data/X_positioning_error.mat';




filePath = "D:\Sync\jbox\recently-used\example-meas-data\XA_Y0A1J5.csv";
fid = fopen(filePath);
for ii = 1:100
    tline = fgetl(fid);
    if contains(tline,'Time,Measurement')
        break;
    end
end

% 设置导入选项并导入数据
opts = detectImportOptions(filePath,"FileType","delimitedtext","NumHeaderLines",ii - 1);

xl80Data = readtable(filePath,opts);
figure; %[output:319bdb47]
plot(xl80Data,"Time","Measurement") %[output:319bdb47]

